require __DIR__.'/config.php';Auth::requireUser();$kategori=new Kategori();$lokasi=new Lokasi();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$d=['nama_barang'=>trim($_POST['nama_barang']??''),'kategori_id'=>(int)($_POST['kategori_id']??0),'lokasi_id'=>(int)($_POST['lokasi_id']??0),'tanggal_hilang'=>$_POST['tanggal_hilang']??'','deskripsi'=>trim($_POST['deskripsi']??''),'foto'=>null,'user_id'=>Auth::user()['id']];if(empty($d['nama_barang'])||empty($d['kategori_id'])||empty($d['lokasi_id'])||empty($d['tanggal_hilang'])||empty($d['deskripsi']))$error='Semua kolom selain foto wajib diisi.';elseif($d['tanggal_hilang']>date('Y-m-d'))$error='Tanggal hilang tidak boleh melebihi hari ini.';else{if(!empty($_FILES['foto']['name'])){$nama=time().'_'.basename($_FILES['foto']['name']);if(move_uploaded_file($_FILES['foto']['tmp_name'],UPLOAD_DIR.$nama))$d['foto']=$nama;}(new Laporan())->create($d);pesan('Laporan tersimpan dan menunggu verifikasi admin.');pindah('histori.php');}}$judul='Buat Laporan';require __DIR__.'/includes/header.php';?><h1 class="h2">Lapor Kehilangan</h1><p class="text-muted">Laporan akan diverifikasi admin sebelum tampil.</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif?><form method="post" enctype="multipart/form-data" class="card card-body"><label class="form-label">Nama barang</label><input class="form-control mb-3" name="nama_barang" value="<?=e($_POST['nama_barang']??'')?>" required><label class="form-label">Kategori</label><select class="form-select mb-3" name="kategori_id" required><option value="">Pilih kategori</option><?php foreach($kategori->all() as $k):?><option value="<?=$k['id']?>"><?=e($k['nama'])?></option><?php endforeach?></select><label class="form-label">Lokasi</label><select class="form-select mb-3" name="lokasi_id" required><option value="">Pilih lokasi</option><?php foreach($lokasi->all() as $l):?><option value="<?=$l['id']?>"><?=e($l['nama'])?></option><?php endforeach?></select><label class="